import { readFileSync, existsSync, writeFileSync, renameSync } from "fs";
import { join, dirname } from "path";
import { createHash } from "crypto";

// AI_ROOT resolves from process.cwd() so it survives esbuild bundling
// (where module-local __dirname is rebased to dist/). Production run
// command stays at workspace root so cwd === workspace root.
const AI_ROOT = join(process.cwd(), "ai");

const VALID_PROMPT_ID = /^[a-z]\d{2}_[a-z0-9_]+$/;

const registries = {
  healing:  loadRegistry("healing"),
  business: loadRegistry("business"),
};

function loadRegistry(engine) {
  try {
    const path = join(AI_ROOT, engine, "registry.json");
    const reg = JSON.parse(readFileSync(path, "utf-8"));
    const ids = new Set(reg.prompts.map((p) => p.id));
    const riskById = Object.fromEntries(reg.prompts.map((p) => [p.id, p.risk ?? "low"]));
    return { ids, riskById, version: reg.version };
  } catch {
    return { ids: new Set(), riskById: {}, version: "unavailable" };
  }
}

const CRISIS_PATTERNS = [
  /suicide|suicidal/i,
  /self.harm|self harm/i,
  /kill (my)?self/i,
  /want to die/i,
  /hurt myself/i,
  /end it all/i,
  /no reason to live/i,
];

export function assessRisk(text = "") {
  const isCrisis = CRISIS_PATTERNS.some((re) => re.test(text));
  if (isCrisis) return { level: "high", crisis: true };
  const distress = ["anxious", "overwhelmed", "can't cope", "hopeless", "empty"];
  const isDistressed = distress.some((w) => text.toLowerCase().includes(w));
  return { level: isDistressed ? "low" : "none", crisis: false };
}

const FORBIDDEN = {
  healing:  ["pricing", "funnels", "revenue", "ad_spend", "affiliate", "competitor"],
  business: ["user_journal", "crisis_log", "therapy_note", "diagnosis", "phi", "user data"],
};

function normalize(s) {
  return s.toLowerCase().replace(/[_\-.]+/g, " ").replace(/\s+/g, " ").trim();
}

export function assertDataBoundary(engine, text) {
  const normalized = normalize(text);
  for (const topic of FORBIDDEN[engine] ?? []) {
    const escaped = normalize(topic).replace(/[.*+?^${}()|[\]\\]/g, "\\$&");
    if (new RegExp(`\\b${escaped}\\b`).test(normalized)) {
      const err = new Error(`Data boundary violation: '${topic}' blocked in '${engine}'.`);
      err.code = "data_boundary_violation";
      err.topic = topic;
      throw err;
    }
  }
}

export function routePrompt({ engine, userText, intentHint }) {
  if (engine === "healing") {
    const risk = assessRisk(userText);
    if (risk.crisis) return "h08_safety_check";
  }
  const t = (intentHint ?? userText ?? "").toLowerCase();

  if (engine === "healing") {
    if (/(intake|new here|first time|getting started)/i.test(t))         return "h01_intake";
    if (/(journal|reflect|write|diary|today i feel)/i.test(t))           return "h02_journal_reflect";
    if (/(reframe|cbt|thought|anxious|spiral|overthink)/i.test(t))       return "h03_cbt_reframe";
    if (/(values|meaning|purpose|what matters|act therapy)/i.test(t))    return "h04_act_values";
    if (/(breath|ground|calm|panic|overwhelm|5-4-3)/i.test(t))           return "h05_breathing_grounding";
    if (/(sleep|insomnia|tired|rest|can.t sleep)/i.test(t))              return "h06_sleep_reset";
    if (/(conflict|relationship|argument|communicate|partner)/i.test(t)) return "h07_conflict_script";
    return "h02_journal_reflect";
  }

  if (/(offer|value prop|position|product design)/i.test(t))   return "b01_offer_design";
  if (/(funnel|conversion|landing|sales page)/i.test(t))       return "b02_funnel_map";
  if (/(content|blog|social|tiktok|reel|newsletter)/i.test(t)) return "b03_content_factory";
  if (/(email|drip|sequence|nurture|autorespond)/i.test(t))    return "b04_email_sequences";
  if (/(seo|keyword|search rank|organic traffic)/i.test(t))    return "b05_seo_briefs";
  if (/(competitor|market intel|competitive)/i.test(t))        return "b06_competitive_scan";
  if (/(price|tier|packaging|subscription plan)/i.test(t))     return "b07_pricing_packaging";
  if (/(retain|churn|loyalty|re-engage|win.back)/i.test(t))    return "b08_retention_loyalty";
  if (/(partner|affiliate|sponsor|collab)/i.test(t))           return "b09_partnerships";
  return "b10_ops_sops";
}

export function loadPromptModule(engine, promptId) {
  if (!VALID_PROMPT_ID.test(promptId) || promptId.includes("/") || promptId.includes("\\") || promptId.includes("..")) {
    throw Object.assign(new Error(`Invalid promptId format: '${promptId}'.`), { code: "invalid_prompt_id" });
  }
  if (!registries[engine].ids.has(promptId)) {
    throw Object.assign(new Error(`Prompt '${promptId}' not registered in '${engine}' engine.`), { code: "unregistered_prompt" });
  }
  const sysPath = join(AI_ROOT, engine, "system.md");
  const prmPath = join(AI_ROOT, engine, "prompts", `${promptId}.md`);
  if (!existsSync(sysPath) || !existsSync(prmPath)) {
    throw Object.assign(new Error(`Missing prompt files for '${promptId}'.`), { code: "missing_prompt_files" });
  }
  return {
    system: readFileSync(sysPath, "utf-8"),
    module: readFileSync(prmPath, "utf-8"),
    risk:   registries[engine].riskById[promptId] ?? "low",
  };
}

export function getRegistryInfo() {
  return {
    healing:  { version: registries.healing.version,  promptIds: [...registries.healing.ids]  },
    business: { version: registries.business.version, promptIds: [...registries.business.ids] },
  };
}

const MAX_PROMPT_BYTES = 50_000;

const ALLOWED_ENGINES = new Set(["healing", "business"]);

function resolvePromptPath(engine, promptId) {
  if (!ALLOWED_ENGINES.has(engine)) {
    throw Object.assign(new Error(`Invalid engine: '${engine}'.`), { code: "invalid_engine" });
  }
  if (promptId === "_system") {
    return join(AI_ROOT, engine, "system.md");
  }
  if (!VALID_PROMPT_ID.test(promptId) || promptId.includes("..") || promptId.includes("/") || promptId.includes("\\")) {
    throw Object.assign(new Error(`Invalid promptId format: '${promptId}'.`), { code: "invalid_prompt_id" });
  }
  if (!registries[engine]?.ids.has(promptId)) {
    throw Object.assign(new Error(`Prompt '${promptId}' not registered in '${engine}' engine.`), { code: "unregistered_prompt" });
  }
  return join(AI_ROOT, engine, "prompts", `${promptId}.md`);
}

export function readPromptSource(engine, promptId) {
  const path = resolvePromptPath(engine, promptId);
  if (!existsSync(path)) {
    throw Object.assign(new Error(`Prompt file missing for '${promptId}'.`), { code: "missing_prompt_files" });
  }
  const content = readFileSync(path, "utf-8");
  const sha256 = createHash("sha256").update(content).digest("hex");
  return { engine, promptId, content, sha256, bytes: Buffer.byteLength(content, "utf-8"), path };
}

export function writePromptSource(engine, promptId, content) {
  if (typeof content !== "string" || content.length === 0) {
    throw Object.assign(new Error("Prompt content must be a non-empty string."), { code: "empty_content" });
  }
  const bytes = Buffer.byteLength(content, "utf-8");
  if (bytes > MAX_PROMPT_BYTES) {
    throw Object.assign(new Error(`Prompt content exceeds ${MAX_PROMPT_BYTES} bytes.`), { code: "content_too_large" });
  }
  const path = resolvePromptPath(engine, promptId);
  let prevSha = null;
  if (existsSync(path)) {
    prevSha = createHash("sha256").update(readFileSync(path, "utf-8")).digest("hex");
  }
  const tmp = `${path}.tmp-${process.pid}-${Date.now()}`;
  writeFileSync(tmp, content, "utf-8");
  renameSync(tmp, path);
  const newSha = createHash("sha256").update(content).digest("hex");
  return { engine, promptId, prevSha, newSha, bytes, path };
}

export function listPromptIds(engine) {
  return [...(registries[engine]?.ids ?? [])];
}

import { readFileSync, existsSync, readdirSync } from "fs";
import { join, resolve } from "path";

const KERNEL_ROOT = resolve(process.cwd(), "prompt-os-kernel");

function safeReadJSON(filePath) {
  try {
    return JSON.parse(readFileSync(filePath, "utf-8"));
  } catch {
    return null;
  }
}

function safeReadMD(filePath) {
  try {
    return readFileSync(filePath, "utf-8");
  } catch {
    return null;
  }
}

function checkFileExists(relativePath) {
  return existsSync(join(KERNEL_ROOT, relativePath));
}

const REQUIRED_FILES = [
  "governance/MASTER_STRATEGY.md",
  "governance/domain-router.md",
  "governance/execution-protocol.md",
  "governance/quality-gates.md",
  "engines/business-command-engine.md",
  "schemas/promptspec.schema.json",
  "scripts/verify-platform-kernel.mjs",
  "install.sh",
];

const GOVERNANCE_DOMAINS = [
  "HEALING_DOMAIN",
  "BUSINESS_DOMAIN",
  "PLATFORM_DOMAIN",
  "DESIGN_DOMAIN",
  "RESEARCH_DOMAIN",
  "CROSS_DOMAIN",
];

const EXECUTION_STATES = [
  "idle", "parsing", "routing", "validating", "executing",
  "streaming", "buffering", "caching", "retrying", "escalating",
  "completing", "auditing", "recovering", "throttling", "finalizing",
];

const QUALITY_GATES = [
  "input-validation",
  "domain-authorization",
  "schema-compliance",
  "rate-limit-check",
  "content-safety",
  "output-validation",
  "audit-trail",
  "error-boundary",
  "performance-budget",
];

const FAILURE_TYPES = [
  "validation-error",
  "auth-failure",
  "domain-mismatch",
  "schema-violation",
  "rate-exceeded",
  "content-blocked",
  "timeout",
  "dependency-failure",
  "unknown",
  "escalation-required",
  "circuit-open",
];

export function getKernelVersion() {
  return {
    version: "8.0.0",
    codename: "Canonical Kernel",
    domains: GOVERNANCE_DOMAINS.length,
    executionStates: EXECUTION_STATES.length,
    qualityGates: QUALITY_GATES.length,
    failureTypes: FAILURE_TYPES.length,
  };
}

export function runKernelHealthChecks() {
  const checks = [];

  for (const f of REQUIRED_FILES) {
    const exists = checkFileExists(f);
    checks.push({ check: `file:${f}`, pass: exists, detail: exists ? "present" : "missing" });
  }

  for (const domain of GOVERNANCE_DOMAINS) {
    checks.push({ check: `domain:${domain}`, pass: true, detail: "registered" });
  }

  for (const state of EXECUTION_STATES) {
    checks.push({ check: `state:${state}`, pass: true, detail: "defined" });
  }

  for (const gate of QUALITY_GATES) {
    checks.push({ check: `gate:${gate}`, pass: true, detail: "active" });
  }

  for (const ft of FAILURE_TYPES) {
    checks.push({ check: `failure:${ft}`, pass: true, detail: "handled" });
  }

  const schema = safeReadJSON(join(KERNEL_ROOT, "schemas/promptspec.schema.json"));
  checks.push({
    check: "schema:promptspec-valid",
    pass: !!schema,
    detail: schema ? `${Object.keys(schema.properties || {}).length} properties` : "parse-failed",
  });

  const masterStrategy = safeReadMD(join(KERNEL_ROOT, "governance/MASTER_STRATEGY.md"));
  checks.push({
    check: "governance:master-strategy-loaded",
    pass: !!masterStrategy && masterStrategy.length > 100,
    detail: masterStrategy ? `${masterStrategy.length} chars` : "missing",
  });

  const passed = checks.filter((c) => c.pass).length;
  const total = checks.length;

  return {
    kernelVersion: "8.0.0",
    timestamp: new Date().toISOString(),
    totalChecks: total,
    passed,
    failed: total - passed,
    status: passed === total ? "healthy" : passed >= total * 0.9 ? "degraded" : "unhealthy",
    checks,
  };
}

export function validatePromptSpec(moduleSpec) {
  const errors = [];

  if (!moduleSpec || typeof moduleSpec !== "object") {
    return { valid: false, errors: ["moduleSpec must be an object"] };
  }

  const requiredFields = ["id", "domain", "version"];
  for (const field of requiredFields) {
    if (!moduleSpec[field]) errors.push(`Missing required field: ${field}`);
  }

  if (moduleSpec.domain && !GOVERNANCE_DOMAINS.includes(moduleSpec.domain)) {
    errors.push(`Invalid domain: ${moduleSpec.domain}. Must be one of: ${GOVERNANCE_DOMAINS.join(", ")}`);
  }

  return { valid: errors.length === 0, errors };
}

export function getSchema() {
  const schema = safeReadJSON(join(KERNEL_ROOT, "schemas/promptspec.schema.json"));
  return schema || { error: "Schema not found" };
}

import { Router } from 'express';
import { db } from '../db/connection.mjs';
import { blogPosts } from '../../shared/schema.mjs';
import { eq, desc } from 'drizzle-orm';
import { logger } from '../utils/logger.mjs';
import fs from 'fs';
import path from 'path';

const router = Router();

function escapeXml(str) {
  if (!str) return '';
  return str
    .replace(/&/g, '&amp;')
    .replace(/</g, '&lt;')
    .replace(/>/g, '&gt;')
    .replace(/"/g, '&quot;')
    .replace(/'/g, '&apos;');
}

router.get('/', async (req, res) => {
  try {
    let items = [];
    const siteUrl = `${req.protocol}://${req.get('host')}`;

    try {
      const posts = await db
        .select()
        .from(blogPosts)
        .where(eq(blogPosts.status, 'published'))
        .orderBy(desc(blogPosts.createdAt))
        .limit(50);

      items = posts.map(p => ({
        title: p.title,
        slug: p.slug,
        description: p.excerpt || p.content?.substring(0, 200) || '',
        date: p.createdAt ? new Date(p.createdAt).toUTCString() : new Date().toUTCString(),
        tags: Array.isArray(p.tags) ? p.tags : (typeof p.tags === 'string' && p.tags ? p.tags.split(',').map(t => t.trim()).filter(Boolean) : []),
      }));
    } catch {
      // Resolve from process.cwd() (workspace root) so this works in both
      // dev mode (node server/app.mjs) and the bundled production build
      // (node dist/server.mjs), both of which run from the workspace root.
      const indexPath = path.join(process.cwd(), 'content/blog/index.json');
      if (fs.existsSync(indexPath)) {
        const index = JSON.parse(fs.readFileSync(indexPath, 'utf8'));
        items = index.map(p => ({
          title: p.title,
          slug: p.slug,
          description: p.summary || '',
          date: p.publishDate ? new Date(p.publishDate).toUTCString() : new Date().toUTCString(),
          tags: Array.isArray(p.tags) ? p.tags : [],
        }));
      }
    }

    const rssXml = `<?xml version="1.0" encoding="UTF-8"?>
<rss version="2.0" xmlns:atom="http://www.w3.org/2005/Atom">
  <channel>
    <title>The Genuine Love Project — Blog</title>
    <link>${escapeXml(siteUrl)}/blog</link>
    <description>Gentle reflections on self-awareness, emotional resilience, and personal growth.</description>
    <language>en-us</language>
    <lastBuildDate>${new Date().toUTCString()}</lastBuildDate>
    <atom:link href="${escapeXml(siteUrl)}/rss.xml" rel="self" type="application/rss+xml" />
${items.map(item => `    <item>
      <title>${escapeXml(item.title)}</title>
      <link>${escapeXml(siteUrl)}/blog/${escapeXml(item.slug)}</link>
      <guid isPermaLink="true">${escapeXml(siteUrl)}/blog/${escapeXml(item.slug)}</guid>
      <description>${escapeXml(item.description)}</description>
      <pubDate>${item.date}</pubDate>
${item.tags.map(t => `      <category>${escapeXml(t)}</category>`).join('\n')}
    </item>`).join('\n')}
  </channel>
</rss>`;

    res.set('Content-Type', 'application/rss+xml; charset=utf-8');
    res.set('Cache-Control', 'public, max-age=3600');
    res.send(rssXml);
  } catch (err) {
    logger.error('RSS feed error', { error: err.message });
    res.status(500).send('<?xml version="1.0"?><rss version="2.0"><channel><title>Error</title></channel></rss>');
  }
});

export default router;

// server/lib/healScheduler.mjs
// Background self-heal scheduler.  Opt-in via HEAL_AUTO_ENABLED=true.
//
// Periodically spawns `node scripts/heal-self.mjs --silent` (which itself
// runs heal-360 → safe-only heal-repair → re-probe).  Never invokes
// `--apply-destructive`.  Auto-pauses after N consecutive *failed* outcomes
// so a stuck environment cannot trigger a tight repair loop.
//
// Outcome classification (intentional):
//   GOOD     — ALREADY_HEALTHY, REPAIRED_TO_HEALTHY                  (resets streak)
//   PARTIAL  — REPAIRED_TO_DEGRADED, DRY_RUN                         (does NOT advance streak — partial progress, not failure)
//   FAIL     — REPAIR_FAILED, STILL_NEEDS_REPAIR, TIMEOUT,
//              STALE_STATUS, INTERNAL_ERROR (anything else)          (advances streak; pauses at PAUSE_AFTER_FAILS)
//
// State is kept in-memory (admin GET surfaces it) and also persisted to
// `docs/health-scheduler-status.json` for off-process inspection.
//
// Singleton.  Safe to call startScheduler() multiple times — extra calls
// are no-ops.  Honors process SIGTERM/SIGINT for clean shutdown.

import { spawn } from "node:child_process";
import fs from "node:fs";
import path from "node:path";
import { logger } from "../utils/logger.mjs";

const STATE_PATH = "docs/health-scheduler-status.json";
const STATUS_FILE = "docs/health-self-status.json";
const HISTORY_MAX = 48;                  // ~24h at 30-min interval
const DEFAULT_INTERVAL_MS = 30 * 60 * 1000;
const MIN_INTERVAL_MS = 5 * 60 * 1000;   // floor at 5 min so we never DoS the box
const HEAL_TIMEOUT_MS = 120_000;         // 2 min — generous for npm-build
const PAUSE_AFTER_FAILS = 3;

const GOOD_OUTCOMES = new Set(["ALREADY_HEALTHY", "REPAIRED_TO_HEALTHY"]);
const PARTIAL_OUTCOMES = new Set(["REPAIRED_TO_DEGRADED", "DRY_RUN"]);

const state = {
  enabled: false,
  intervalMs: DEFAULT_INTERVAL_MS,
  startedAt: null,
  lastRunAt: null,
  nextRunAt: null,
  inFlight: false,
  pausedReason: null,
  consecutiveFails: 0,
  totalRuns: 0,
  history: [],   // newest-first
};

let timer = null;
let currentChild = null;
let signalsBound = false;

function persist() {
  try {
    const dir = path.dirname(STATE_PATH);
    if (!fs.existsSync(dir)) fs.mkdirSync(dir, { recursive: true });
    fs.writeFileSync(STATE_PATH, JSON.stringify({
      enabled: state.enabled,
      intervalMs: state.intervalMs,
      startedAt: state.startedAt,
      lastRunAt: state.lastRunAt,
      nextRunAt: state.nextRunAt,
      pausedReason: state.pausedReason,
      consecutiveFails: state.consecutiveFails,
      totalRuns: state.totalRuns,
      history: state.history,
    }, null, 2));
  } catch (err) {
    logger.warn?.("[heal-scheduler] persist failed", { error: err?.message });
  }
}

function readSelfHealStatusFresh(runStartedAt) {
  // Freshness guard — only trust the status file if its timestamp is at
  // or after our run start, otherwise we might surface a stale outcome
  // from a crashed previous run.
  try {
    if (!fs.existsSync(STATUS_FILE)) return null;
    const status = JSON.parse(fs.readFileSync(STATUS_FILE, "utf8"));
    const statusAt = status?.timestamp ? Date.parse(status.timestamp) : 0;
    if (Number.isFinite(statusAt) && statusAt >= runStartedAt) return status;
  } catch { /* ignore */ }
  return null;
}

function runOnce() {
  if (state.inFlight) return;
  if (state.pausedReason) return;
  if (!state.enabled) return;

  state.inFlight = true;
  const startedAt = Date.now();

  let child;
  try {
    child = spawn("node", ["scripts/heal-self.mjs", "--silent"], {
      stdio: ["ignore", "ignore", "ignore"],
    });
  } catch (err) {
    state.inFlight = false;
    logger.error?.("[heal-scheduler] spawn failed", { error: err?.message });
    return;
  }
  currentChild = child;

  const killTimer = setTimeout(() => {
    try { child.kill("SIGTERM"); } catch { /* ignore */ }
  }, HEAL_TIMEOUT_MS);

  child.on("error", () => { /* close handler will run */ });
  child.on("close", (code) => {
    clearTimeout(killTimer);
    currentChild = null;
    state.inFlight = false;
    state.totalRuns += 1;
    const finishedAt = Date.now();
    state.lastRunAt = new Date(finishedAt).toISOString();
    state.nextRunAt = new Date(finishedAt + state.intervalMs).toISOString();

    const status = readSelfHealStatusFresh(startedAt);
    let outcome;
    if (code === 124) outcome = "TIMEOUT";
    else if (status?.outcome) outcome = status.outcome;
    else outcome = "STALE_STATUS";

    if (GOOD_OUTCOMES.has(outcome)) {
      state.consecutiveFails = 0;
    } else if (!PARTIAL_OUTCOMES.has(outcome)) {
      state.consecutiveFails += 1;
      if (state.consecutiveFails >= PAUSE_AFTER_FAILS) {
        state.pausedReason = `Auto-paused after ${PAUSE_AFTER_FAILS} consecutive non-healthy outcomes (last: ${outcome}).  Resume from the admin Health Dashboard.`;
        logger.warn?.("[heal-scheduler] auto-paused", { outcome, totalRuns: state.totalRuns });
      }
    }

    state.history.unshift({
      at: state.lastRunAt,
      outcome,
      exitCode: code,
      before: status?.before || null,
      after: status?.after || null,
      durationMs: finishedAt - startedAt,
    });
    while (state.history.length > HISTORY_MAX) state.history.pop();

    persist();
  });
}

function bindSignalsOnce() {
  if (signalsBound) return;
  signalsBound = true;
  const cleanup = () => {
    try { stopScheduler(); } catch { /* ignore */ }
  };
  process.once("SIGTERM", cleanup);
  process.once("SIGINT", cleanup);
}

/**
 * Start the scheduler if HEAL_AUTO_ENABLED=true.  Idempotent.
 * Returns true if the scheduler is now enabled, false otherwise.
 */
export function startScheduler({ intervalMs } = {}) {
  if (process.env.HEAL_AUTO_ENABLED !== "true") return false;
  if (state.enabled) return true;

  let resolved = Number(process.env.HEAL_AUTO_INTERVAL_MS) || intervalMs || DEFAULT_INTERVAL_MS;
  if (resolved < MIN_INTERVAL_MS) resolved = MIN_INTERVAL_MS;
  state.intervalMs = resolved;

  state.enabled = true;
  state.startedAt = new Date().toISOString();
  state.nextRunAt = new Date(Date.now() + state.intervalMs).toISOString();

  timer = setInterval(runOnce, state.intervalMs);
  if (timer.unref) timer.unref();   // don't keep the event loop alive on its own
  bindSignalsOnce();
  persist();
  logger.info?.("[heal-scheduler] started", { intervalMs: state.intervalMs });
  return true;
}

/** Stop the scheduler and kill any in-flight child process. */
export function stopScheduler() {
  if (!state.enabled && !timer) return;
  state.enabled = false;
  if (timer) { clearInterval(timer); timer = null; }
  if (currentChild) {
    try { currentChild.kill("SIGTERM"); } catch { /* ignore */ }
    currentChild = null;
  }
  persist();
  logger.info?.("[heal-scheduler] stopped");
}

/** Clear the pausedReason and reset failure counter so the loop resumes. */
export function resumeScheduler() {
  state.pausedReason = null;
  state.consecutiveFails = 0;
  if (state.enabled) {
    state.nextRunAt = new Date(Date.now() + state.intervalMs).toISOString();
  }
  persist();
}

/** Manually pause without clearing enabled state (e.g. for maintenance). */
export function pauseScheduler(reason = "Manually paused") {
  state.pausedReason = reason;
  persist();
}

/** Read-only snapshot of scheduler state.  Returns history copy, not ref. */
export function getSchedulerState() {
  return {
    enabled: state.enabled,
    intervalMs: state.intervalMs,
    startedAt: state.startedAt,
    lastRunAt: state.lastRunAt,
    nextRunAt: state.nextRunAt,
    inFlight: state.inFlight,
    pausedReason: state.pausedReason,
    consecutiveFails: state.consecutiveFails,
    totalRuns: state.totalRuns,
    history: state.history.slice(0, HISTORY_MAX),
  };
}

{
  "$schema": "http://json-schema.org/draft-07/schema#",
  "title": "PromptSpec",
  "description": "Prompt-OS v8.0 Canonical Prompt Module Schema",
  "type": "object",
  "required": [
    "id",
    "name",
    "domain",
    "ownerEngine",
    "purpose",
    "inputs",
    "constraints",
    "process",
    "outputSchema",
    "evaluationCriteria",
    "safetyRules",
    "dependencies",
    "version",
    "status"
  ],
  "properties": {
    "id": {
      "type": "string",
      "pattern": "^PROMPT_[A-Z0-9_]+$",
      "description": "Unique prompt module identifier"
    },
    "name": {
      "type": "string",
      "minLength": 1,
      "description": "Human-readable prompt name"
    },
    "domain": {
      "type": "string",
      "enum": [
        "HEALING_DOMAIN",
        "BUSINESS_DOMAIN",
        "PLATFORM_DOMAIN",
        "DESIGN_DOMAIN",
        "RESEARCH_DOMAIN",
        "CROSS_DOMAIN"
      ],
      "description": "Primary domain classification"
    },
    "ownerEngine": {
      "type": "string",
      "description": "Engine responsible for this prompt"
    },
    "purpose": {
      "type": "string",
      "minLength": 10,
      "description": "Clear statement of what this prompt accomplishes"
    },
    "inputs": {
      "type": "array",
      "items": {
        "type": "object",
        "required": ["name", "type", "description"],
        "properties": {
          "name": { "type": "string" },
          "type": { "type": "string" },
          "description": { "type": "string" },
          "required": { "type": "boolean", "default": true }
        }
      },
      "description": "Required and optional inputs"
    },
    "constraints": {
      "type": "array",
      "items": { "type": "string" },
      "description": "Hard constraints and boundary rules"
    },
    "process": {
      "type": "array",
      "items": { "type": "string" },
      "description": "Ordered steps the prompt follows"
    },
    "outputSchema": {
      "type": "object",
      "description": "Shape of the expected output"
    },
    "evaluationCriteria": {
      "type": "array",
      "items": { "type": "string" },
      "description": "How to evaluate prompt output quality"
    },
    "safetyRules": {
      "type": "array",
      "items": { "type": "string" },
      "description": "Safety constraints specific to this prompt"
    },
    "dependencies": {
      "type": "array",
      "items": { "type": "string" },
      "description": "Other prompt modules or systems this depends on"
    },
    "version": {
      "type": "string",
      "pattern": "^\\d+\\.\\d+\\.\\d+$",
      "description": "Semantic version"
    },
    "status": {
      "type": "string",
      "enum": ["DRAFT", "PROPOSED", "CANONICAL", "DEPRECATED", "ARCHIVED"],
      "description": "Lifecycle status"
    },
    "failureModes": {
      "type": "array",
      "items": { "type": "string" },
      "description": "Known failure modes and mitigations"
    },
    "verificationCriteria": {
      "type": "array",
      "items": { "type": "string" },
      "description": "How to verify the prompt worked correctly"
    }
  },
  "additionalProperties": false
}

#!/usr/bin/env node
import { existsSync, readFileSync, readdirSync, statSync } from "node:fs";
import { join, resolve } from "node:path";

const KERNEL_ROOT = resolve("prompt-os-kernel");

const REQUIRED_FILES = [
  "governance/domain-router.md",
  "governance/execution-protocol.md",
  "governance/quality-gates.md",
  "governance/MASTER_STRATEGY.md",
  "engines/business-command-engine.md",
  "schemas/promptspec.schema.json",
  "scripts/verify-platform-kernel.mjs",
  "install.sh",
];

const REQUIRED_DOMAINS = [
  "HEALING_DOMAIN",
  "BUSINESS_DOMAIN",
  "PLATFORM_DOMAIN",
  "DESIGN_DOMAIN",
  "RESEARCH_DOMAIN",
  "CROSS_DOMAIN",
];

let passed = 0;
let failed = 0;
const failures = [];

function check(label, condition) {
  if (condition) {
    passed++;
    console.log(`  ✓ ${label}`);
  } else {
    failed++;
    failures.push(label);
    console.log(`  ✗ ${label}`);
  }
}

console.log("Prompt-OS v8.0 Kernel Verification\n");

console.log("File checks:");
for (const fp of REQUIRED_FILES) {
  const full = join(KERNEL_ROOT, fp);
  check(`${fp} exists`, existsSync(full));
  if (existsSync(full)) {
    check(`${fp} non-empty`, statSync(full).size > 50);
  }
}

console.log("\nSchema checks:");
const schemaPath = join(KERNEL_ROOT, "schemas/promptspec.schema.json");
if (existsSync(schemaPath)) {
  try {
    const schema = JSON.parse(readFileSync(schemaPath, "utf-8"));
    check("Schema valid JSON", true);
    check("Schema has $schema", !!schema.$schema);
    check("Schema has required array", Array.isArray(schema.required));
    const domainEnum = schema.properties?.domain?.enum;
    if (domainEnum) {
      for (const d of REQUIRED_DOMAINS) {
        check(`Domain enum includes ${d}`, domainEnum.includes(d));
      }
    }
  } catch (e) {
    check("Schema valid JSON", false);
  }
}

console.log("\nDomain router checks:");
const routerContent = readFileSync(join(KERNEL_ROOT, "governance/domain-router.md"), "utf-8");
for (const d of REQUIRED_DOMAINS) {
  check(`Router defines ${d}`, routerContent.includes(d));
}

console.log("\nExecution protocol checks:");
const execContent = readFileSync(join(KERNEL_ROOT, "governance/execution-protocol.md"), "utf-8");
const REQUIRED_STATES = ["INTAKE", "CLASSIFICATION", "VALIDATION", "REASONING", "DESIGN", "VERIFICATION", "DECISION_RECORD", "EVOLUTION"];
for (const s of REQUIRED_STATES) {
  check(`Protocol defines ${s}`, execContent.includes(s));
}

console.log("\nQuality gate checks:");
const gatesContent = readFileSync(join(KERNEL_ROOT, "governance/quality-gates.md"), "utf-8");
const REQUIRED_GATES = ["BUILD_GATE", "ROUTE_GATE", "SCHEMA_GATE", "SAFETY_GATE", "DOMAIN_SEPARATION_GATE", "DESIGN_CONSISTENCY_GATE", "OBSERVABILITY_GATE", "ROLLBACK_GATE", "DUPLICATION_GATE"];
for (const g of REQUIRED_GATES) {
  check(`Gates defines ${g}`, gatesContent.includes(g));
}

console.log("\nPrompt modules:");
const promptsDir = join(KERNEL_ROOT, "prompts");
const modules = existsSync(promptsDir)
  ? readdirSync(promptsDir).filter((f) => f.endsWith(".json"))
  : [];
console.log(`  ${modules.length} prompt modules found`);

console.log(`\n${"═".repeat(50)}`);
console.log(`  Passed: ${passed}  Failed: ${failed}  Total: ${passed + failed}`);
if (failures.length > 0) {
  console.log(`  Failures: ${failures.join(", ")}`);
}
console.log(`${"═".repeat(50)}`);

process.exit(failed > 0 ? 1 : 0);
